import AppKit
import EdithExtensionUI
import Foundation

@MainActor enum HostMarketplaceArtwork {
    private static var cachedTheme: String?
    private static var cached: [NSImage] = []
    static func swatches(theme: String) -> [NSImage] {
        let theme = AppTheme(storedName: theme).rawValue
        if cachedTheme == theme { return cached }
        cached = ["edith-" + theme, "claude-accent", "finder-accent", "spotify-accent"].compactMap(
            image)
        cachedTheme = theme
        return cached
    }
    static func image(_ key: String) -> NSImage? {
        guard let encoded = images[key], let packed = Data(base64Encoded: encoded),
            let pixels = try? (packed as NSData).decompressed(using: .lzfse) as Data,
            pixels.count == 1024 * 150, let provider = CGDataProvider(data: pixels as CFData),
            let image = CGImage(
                width: 252, height: 150, bitsPerComponent: 8, bitsPerPixel: 32,
                bytesPerRow: 1024, space: CGColorSpace(name: CGColorSpace.sRGB)!,
                bitmapInfo: CGBitmapInfo(
                    rawValue: CGImageAlphaInfo.premultipliedFirst.rawValue
                        | CGImageByteOrderInfo.order32Host.rawValue),
                provider: provider, decode: nil, shouldInterpolate: true, intent: .defaultIntent)
        else { return nil }
        return NSImage(cgImage: image, size: NSSize(width: 84, height: 50))
    }
    private static let images: [String: String] = [
        "claude-accent":
            "",
        "edith-accent":
            "",
        "edith-blue":
            "",
        "edith-green":
            "",
        "edith-indigo":
            "",
        "edith-orange":
            "",
        "edith-pink":
            "",
        "edith-purple":
            "",
        "edith-red":
            "",
        "edith-teal":
            "",
        "finder-accent":
            "",
        "spotify-accent":
            "",
    ]
}
